import json, re, sqlite3, sys
from http.server import BaseHTTPRequestHandler, HTTPServer
training = [("reset password login", "account"), ("sign in account", "account"),
            ("invoice payment receipt", "billing"), ("charge billing", "billing")]
def tokens(text):
    return set(re.findall(r"[a-z]+", text.lower()))
def predict(text):
    query = tokens(text)
    scored = [(len(query & tokens(example)), label) for example, label in training]
    score, label = max(scored)
    return label if score else "review"
def validate(payload):
    if not isinstance(payload, dict) or set(payload) != {"text"}:
        raise ValueError("Expected one text field")
    text = payload["text"]
    if not isinstance(text, str) or not 1 <= len(text.strip()) <= 500:
        raise ValueError("Use 1 to 500 characters")
    return text.strip()
class Handler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        pass  # Do not log request content in this learning service.
    def reply(self, status, data):
        body = json.dumps(data).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(body)
    def do_POST(self):
        if self.path != "/predict":
            return self.reply(404, {"error": "Not found"})
        if self.headers.get_content_type() != "application/json":
            return self.reply(415, {"error": "Use application/json"})
        try:
            size = int(self.headers.get("Content-Length", "0"))
            if not 0 < size <= 4096:
                return self.reply(413, {"error": "Body must be 1 to 4096 bytes"})
            payload = json.loads(self.rfile.read(size))
            label = predict(validate(payload))
        except (ValueError, UnicodeError):
            return self.reply(400, {"error": "Invalid JSON or text"})
        with sqlite3.connect("academy_predictions.sqlite3") as db:
            db.execute("CREATE TABLE IF NOT EXISTS predictions (id INTEGER PRIMARY KEY, label TEXT NOT NULL)")
            result = db.execute("INSERT INTO predictions (label) VALUES (?)", (label,))
            prediction_id = result.lastrowid
        self.reply(200, {"id": prediction_id, "label": label})
if __name__ == "__main__":
    if "--serve" in sys.argv:
        print("Local learning API: http://127.0.0.1:8000/predict")
        HTTPServer(("127.0.0.1", 8000), Handler).serve_forever()
    else:
        assert predict(validate({"text": "reset password"})) == "account"
        assert predict("galactic weather") == "review"
        print("Self-test passed. Add --serve to run the local API.")
